template <typename T = double, int N = 5>
struct Matrix {
    T arr[N];

    // Constructor utilizes default argument
    Matrix(T init_val = {}) {
        for(auto& x : arr) x = init_val;
    }
};

Matrix<> m1;              // Uses T=double, N=5
Matrix<int> m2;           // Uses T=int, N=5
Matrix<bool, 8> m3;       // Uses T=bool, N=8
Matrix<float> m4(1.0f);   // Uses T=float, N=5
Matrix<long, 3> m5;       // Uses T=long, N=3
// Note: Arguments must be specified left-to-right.
